contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory v) public {
        require(tos.length > 0);
        require(tos.length == v.length);
        for (uint i = 0; i < v.length; i++) {
            require(v[i] == 0 || (v[i] * 1000000000000000000) / v[i] == 1000000000000000000);
        }

        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.transfer(tos, v) returns (bool ret) {
            reverted = false;
            assert(ret == true);
            assert(address(c).balance == beforeBalance);
        } catch {
            reverted = true;
        }
        assert(reverted || address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

