contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory vs) public payable {
        // The caller of the inner `transfer` is this test contract (msg.sender != 0x9797...), so
        // the `require(msg.sender == 0x9797...)` must fail for every input.
        bool reverted;
        try c.transfer(tos, vs) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call must always revert because the fixed sender check fails.
        assert(reverted);
    }

    receive() external payable {}
}

